/* ============ ডেটা: ব্যবহারিক (ব্যাংক ডেটাবেজ) ============ */
const SETUP=`CREATE DATABASE bank_db;
USE bank_db;

CREATE TABLE Branch (
  Branch_ID   VARCHAR(15) PRIMARY KEY,
  Branch_Name VARCHAR(30),
  Branch_City VARCHAR(30)
);
CREATE TABLE Account (
  Account_No VARCHAR(15) PRIMARY KEY,
  Cust_Name  VARCHAR(30),
  Branch_ID  VARCHAR(15),
  FOREIGN KEY (Branch_ID) REFERENCES Branch(Branch_ID)
);
CREATE TABLE Depositor (
  Account_No VARCHAR(15),
  Branch_ID  VARCHAR(15),
  Balance    DECIMAL(12,2),
  FOREIGN KEY (Account_No) REFERENCES Account(Account_No),
  FOREIGN KEY (Branch_ID)  REFERENCES Branch(Branch_ID)
);
CREATE TABLE Loan (
  Account_No VARCHAR(15),
  Branch_ID  VARCHAR(15),
  Balance    DECIMAL(12,2),
  FOREIGN KEY (Account_No) REFERENCES Account(Account_No),
  FOREIGN KEY (Branch_ID)  REFERENCES Branch(Branch_ID)
);

-- নিয়ম: আগে Branch, তারপর Account, তারপর Depositor/Loan (parent আগে)
INSERT INTO Branch VALUES
 ('SB001','Malleshwaram','Bangalore'),('SB002','MG Road','Bangalore'),
 ('SB003','MG Road','Mysore'),('SB004','Jainagar','Mysore');
INSERT INTO Account VALUES
 ('AE0012856','Reena','SB002'),('AE1185698','Akhil','SB001'),
 ('AE1203996','Daniel','SB004'),('AE1225889','Roy','SB002'),
 ('AE8532166','Sowparnika','SB003'),('AE8552266','Anil','SB003'),
 ('AE1003996','Saathwik','SB004'),('AE1100996','Swarna','SB002');
INSERT INTO Depositor VALUES
 ('AE0012856','SB002',12000),('AE1203996','SB004',58900),
 ('AE8532166','SB003',40000),('AE1225889','SB002',150000);
INSERT INTO Loan VALUES
 ('AE1185698','SB001',102000),('AE8552266','SB003',40000),
 ('AE1003996','SB004',15000),('AE1100996','SB002',100000);`;

