const ICSETUP=`CREATE DATABASE bank_test;
USE bank_test;
CREATE TABLE Customer (
  customer_id INT PRIMARY KEY, name VARCHAR(100) NOT NULL,
  account_type VARCHAR(20), balance DECIMAL(12,2) DEFAULT 0 CHECK (balance >= 0), branch_id INT);
-- Transaction MySQL-এ reserved শব্দ, তাই backtick
CREATE TABLE \`Transaction\` (
  transaction_id INT PRIMARY KEY, customer_id INT, amount DECIMAL(12,2),
  transaction_type VARCHAR(10), status VARCHAR(20), transaction_date DATE,
  FOREIGN KEY (customer_id) REFERENCES Customer(customer_id));
INSERT INTO Customer VALUES (1,'Rahim Uddin','Savings',45000,1),(2,'Karim Ahmed','Current',78500,1),(3,'Salma Khatun','Savings',32000,2);
INSERT INTO \`Transaction\` VALUES
 (101,1,10000,'Withdrawal','Completed','2026-09-01'),(102,1,50000,'Deposit','Completed','2026-09-05'),
 (103,2,25000,'Deposit','Pending','2026-09-03'),(104,2,60000,'Withdrawal','Failed','2026-09-06'),
 (105,1,45000,'Deposit','Completed','2026-09-10');`;
const I=(q,a,o)=>({db:'icml',q,ans:a,ok:[a],out:o,bn:'ICML প্রশ্ন — নিজে লিখে মেলাও, তারপর সমাধান দেখো'});
const X='FROM `Transaction`';
P.push(
I('৪০,০০০-এর বেশি transaction-এর সংখ্যা ও মোট amount।','SELECT COUNT(*) AS transaction_count, SUM(amount) AS total_amount '+X+' WHERE amount > 40000;','<p>3 | 155000</p>'),
I('উপরেরটাই, শুধু status = Completed।','SELECT COUNT(*) AS transaction_count, SUM(amount) AS total_amount '+X+" WHERE amount > 40000 AND status = 'Completed';",'<p>2 | 95000</p>'),
I('প্রতি status-এ transaction সংখ্যা।','SELECT status, COUNT(*) AS cnt '+X+' GROUP BY status;','<p>Completed 3 | Pending 1 | Failed 1</p>'),
I('প্রতি customer-এর মোট transaction amount।','SELECT customer_id, SUM(amount) AS total '+X+' GROUP BY customer_id;','<p>1 → 105000 | 2 → 85000</p>'),
I('সর্বোচ্চ মোট transaction-এর customer।','SELECT customer_id, SUM(amount) AS total '+X+' GROUP BY customer_id ORDER BY total DESC LIMIT 1;','<p>1 | 105000</p>'),
I('গড় balance-এর চেয়ে বেশি balance-এর customer।','SELECT * FROM Customer WHERE balance > (SELECT AVG(balance) FROM Customer);','<p>Karim Ahmed (78500) — গড় ≈ 51833.33</p>'),
I('যাদের কোনো transaction নেই (LEFT JOIN)।','SELECT c.customer_id, c.name FROM Customer c LEFT JOIN `Transaction` t ON c.customer_id = t.customer_id WHERE t.transaction_id IS NULL;','<p>3 | Salma Khatun</p>'),
I('Customer-এর নামসহ transaction তালিকা (INNER JOIN)।','SELECT c.name, t.transaction_id, t.amount, t.status FROM Customer c INNER JOIN `Transaction` t ON c.customer_id = t.customer_id;','<p>৫টি row: Rahim ×3, Karim ×2</p>'),
I('Completed transaction-এর মোট ১,০০,০০০-এর বেশি এমন customer (JOIN+GROUP BY+HAVING)।',"SELECT c.customer_id, c.name, SUM(t.amount) AS total_completed FROM Customer c JOIN `Transaction` t ON c.customer_id = t.customer_id WHERE t.status = 'Completed' GROUP BY c.customer_id, c.name HAVING SUM(t.amount) > 100000;",'<p>1 | Rahim Uddin | 105000</p>'),
I('Duplicate transaction (একই customer, amount, date) খুঁজে বের করো।','SELECT customer_id, amount, transaction_date, COUNT(*) AS cnt '+X+' GROUP BY customer_id, amount, transaction_date HAVING COUNT(*) > 1;','<p>কোনো row নেই</p>'),
I('দ্বিতীয় সর্বোচ্চ transaction amount।','SELECT MAX(amount) AS second_highest '+X+' WHERE amount < (SELECT MAX(amount) '+X+');','<p>50000</p>'),
I('Amount অনুযায়ী Very High (>100000) / High (>40000) / Medium (>10000) / Low (CASE)।','SELECT transaction_id, amount, CASE WHEN amount > 100000 THEN \'Very High\' WHEN amount > 40000 THEN \'High\' WHEN amount > 10000 THEN \'Medium\' ELSE \'Low\' END AS category '+X+';','<p>101 Low | 102 High | 103 Medium | 104 High | 105 High</p>'),
I('মোট deposit ও withdrawal।',"SELECT SUM(CASE WHEN transaction_type='Deposit' THEN amount ELSE 0 END) AS total_deposit, SUM(CASE WHEN transaction_type='Withdrawal' THEN amount ELSE 0 END) AS total_withdrawal "+X+';','<p>deposit 120000 | withdrawal 70000</p>'),
I('প্রতি customer-এর net (deposit − withdrawal)।',"SELECT customer_id, SUM(CASE WHEN transaction_type='Deposit' THEN amount ELSE -amount END) AS net "+X+' GROUP BY customer_id;','<p>1 → 85000 | 2 → -35000</p>'),
I('Customer-দের balance বেশি থেকে কম ক্রমে সাজাও।','SELECT * FROM Customer ORDER BY balance DESC;','<p>Karim 78500 → Rahim 45000 → Salma 32000</p>')
// ➕ [নতুন ICML সমস্যা এখানে যোগ করো] — I('প্রশ্ন','সঠিক SQL','<p>আউটপুট</p>'),
);

